<?php require_once __DIR__.'/../api/bootstrap.php';require_login();$m=current_medico();$err='';$aid=(int)($_GET['atendimento_id']??0);$s=db()->prepare('SELECT id,nome FROM pacientes WHERE medico_id=? ORDER BY nome');$s->execute([$m['id']]);$ps=$s->fetchAll();$pre=[];if($aid){$s=db()->prepare('SELECT * FROM atendimentos WHERE id=? AND medico_id=?');$s->execute([$aid,$m['id']]);$pre=$s->fetch()?:[];}if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$pid=(int)$_POST['paciente_id'];$p=patient_for_doctor($pid,$m['id']);$v=[];foreach(['titulo','cid_codigo','cid_descricao','inicio_afastamento','fim_afastamento','atividade_habitual','incapacidade_restricao','info_clinica','observacoes','conteudo_personalizado'] as $f)$v[$f]=trim($_POST[$f]??'');$dias=(int)($_POST['dias_afastamento']??0);if(!$p)$err='Paciente inválido.';elseif(!$v['inicio_afastamento']||!$v['fim_afastamento']||$dias<1)$err='Informe o período e os dias de afastamento.';elseif(empty($_POST['confirmar']))$err='Confirme a revisão médica.';else{$code=unique_code('ATEST');$q=db()->prepare('INSERT INTO atestados(paciente_id,medico_id,atendimento_id,codigo_validacao,data_emissao,titulo,conteudo_personalizado,cid_codigo,cid_descricao,inicio_afastamento,fim_afastamento,dias_afastamento,atividade_habitual,incapacidade_restricao,info_clinica,observacoes,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$pid,$m['id'],$aid?:null,$code,date('Y-m-d H:i:s'),$v['titulo']?:'Atestado Médico',$v['conteudo_personalizado'],$v['cid_codigo'],$v['cid_descricao'],$v['inicio_afastamento'],$v['fim_afastamento'],$dias,$v['atividade_habitual'],$v['incapacidade_restricao'],$v['info_clinica'],$v['observacoes'],'EMITIDO']);$id=db()->lastInsertId();audit_log('emitir_atestado','atestados',$id,['codigo'=>$code]);header('Location:view.php?id='.$id);exit;}}render_header('Novo atestado');?><h1>Atestado médico personalizado</h1><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="card"><div class="grid"><div><label>Paciente *</label><select name="paciente_id" required><option value="">Selecione</option><?php foreach($ps as $p):?><option value="<?=$p['id']?>"><?=e($p['nome'])?></option><?php endforeach;?></select></div><div><label>Título</label><input name="titulo" value="Atestado Médico"></div><div><label>Início *</label><input type="date" name="inicio_afastamento" required></div><div><label>Fim *</label><input type="date" name="fim_afastamento" required></div><div><label>Dias *</label><input type="number" name="dias_afastamento" min="1" required></div><div><label>Atividade habitual</label><input name="atividade_habitual"></div></div></div><div class="card"><h2>CID-10</h2><div class="grid"><div><label>Código</label><input id="cc" name="cid_codigo" autocomplete="off"><div id="cr" class="cid-results"></div></div><div><label>Descrição</label><input id="cd" name="cid_descricao"></div></div></div><div class="card"><label>Incapacidade/restrição funcional</label><textarea name="incapacidade_restricao"></textarea><label>Informações clínicas</label><textarea name="info_clinica"></textarea><label>Observações</label><textarea name="observacoes"></textarea></div><div class="card"><label>Texto personalizado do documento</label><textarea name="conteudo_personalizado" rows="12" placeholder="Se preenchido, este será o corpo principal do atestado."></textarea></div><div class="card"><label><input type="checkbox" name="confirmar" value="1" required> Revisei paciente, diagnóstico/CID, período e texto. Autorizo a emissão e assinatura.</label></div><button class="btn ok">Assinar e emitir</button></form><script>const c=document.querySelector('#cc'),d=document.querySelector('#cd'),r=document.querySelector('#cr');let t;c.oninput=()=>{clearTimeout(t);if(c.value.length<2){r.innerHTML='';return}t=setTimeout(()=>fetch('/medical/cid/search.php?q='+encodeURIComponent(c.value)).then(x=>x.json()).then(a=>r.innerHTML=a.map(x=>'<button type="button" onclick="pick(\''+x.codigo+'\',\''+x.descricao.replaceAll("'","\\'")+'\')"><b>'+x.codigo+'</b> — '+x.descricao+'</button>').join('')),250)};function pick(a,b){c.value=a;d.value=b;r.innerHTML='';}</script><?php render_footer();?>